63	/// Writes Kanata pipeline visualization format.
64	/// Port of Python KanataLogger from tools/utils.py.
65	///
66	/// Format reference:
67	/// https://github.com/shioyadan/Konata/blob/master/docs/kanata-log-format.md
68	class KanataLogger
69	{
70	public:
71	  /// File-based output (existing behavior).
72	  explicit KanataLogger(const std::string& filename,
73	                        std::optional<LoopGate> gate = std::nullopt)
74	      : gate_(gate)
75	      , enabled_(!gate_.has_value())
76	  {
77	    owned_file_.open(filename);
78	    if (!owned_file_.is_open()) {
79	      spdlog::critical("Failed to open kanata log file: {}", filename);
80	      return;
81	    }
82	    output_ = &owned_file_;
83	    write_header();
84	    spdlog::info("Writing kanata pipeline log to {}", filename);
85	    if (gate_)
86	      spdlog::info(
87	        "Kanata loop gate: start={:#x} end={:#x} skip={} record={}",
88	        gate_->start_pc, gate_->end_pc, gate_->skip_iters,
89	        gate_->record_iters);
90	  }
91	
92	  /// Stream-based output (caller owns the ostream lifetime).
93	  explicit KanataLogger(std::ostream& os,
94	                        std::optional<LoopGate> gate = std::nullopt)
95	      : output_(&os)
96	      , gate_(gate)
97	      , enabled_(!gate_.has_value())
98	  {
99	    write_header();
100	  }
101	
102	  ~KanataLogger() { flush_all(); }
103	
104	  KanataLogger(const KanataLogger&) = delete;
105	  KanataLogger& operator=(const KanataLogger&) = delete;
106	
107	  void advance_cycle(int cycles)
108	  {
109	    total_cycles_ += static_cast<uint64_t>(cycles);
110	    if (enabled_)
111	      *output_ << "C\t" << cycles << '\n';
112	  }
113	
114	  void start_insn(uint64_t pc, uint64_t id)
115	  {
116	    id_to_pc_[id] = pc;
117	    maybe_open_window(pc);
118	    if (!enabled_)
119	      return;
120	    inflight_.insert(id);
121	    *output_ << fmt::format("I\t{}\t{}\t0\n", id, id);
122	    auto it = code_map_.find(pc);
123	    auto code = (it != code_map_.end()) ? it->second : std::string{};
124	    *output_ << fmt::format("L\t{}\t0\t{:#x}: {}\n", id, pc, code);
125	  }
126	
127	  /// Start instruction without PC (OoO: PC unknown at issue time).
128	  /// Use label_insn() later to back-fill the PC at commit.
129	  void start_insn_deferred(uint64_t id)
130	  {
131	    if (!enabled_)
132	      return;
133	    inflight_.insert(id);
134	    *output_ << fmt::format("I\t{}\t{}\t0\n", id, id);
135	  }
136	
137	  /// Back-fill label for a deferred instruction (OoO commit).
138	  void label_insn(uint64_t id, uint64_t pc,
139	                  std::string_view suffix = "")
140	  {
141	    id_to_pc_[id] = pc;
142	    if (!is_inflight(id))
143	      return;
144	    auto it = code_map_.find(pc);
145	    auto code = (it != code_map_.end()) ? it->second : std::string{};
146	    if (suffix.empty())
147	      *output_ << fmt::format("L\t{}\t0\t{:#x}: {}\n", id, pc, code);
148	    else
149	      *output_ << fmt::format("L\t{}\t0\t{:#x}: {} [{}]\n", id, pc, code,
150	                              suffix);
151	  }
152	
153	  void retire_insn(uint64_t id)
154	  {
155	    bool emitted = false;
156	    if (remove_inflight(id)) {
157	      *output_ << fmt::format("R\t{}\t{}\t0\n", id, id);
158	      ++recorded_insns_;
159	      emitted = true;
160	    }
161	    on_retire_pc(id, emitted);
162	  }
163	
164	  void flush_insn(uint64_t id)
165	  {
166	    if (remove_inflight(id))
167	      *output_ << fmt::format("R\t{}\t0\t1\n", id);
168	    id_to_pc_.erase(id);
169	  }
170	
171	  void stage_insn(uint64_t id, std::string_view stage_name, int lane_id = 0)
172	  {
173	    if (is_inflight(id))
174	      *output_ << fmt::format("S\t{}\t{}\t{}\n", id, lane_id, stage_name);
175	  }
176	
177	  void end_stage_insn(uint64_t id, std::string_view stage_name)
178	  {
179	    if (is_inflight(id))
180	      *output_ << fmt::format("E\t{}\t0\t{}\n", id, stage_name);
181	  }
182	
183	  void comment_insn(uint64_t id, std::string_view msg)
184	  {
185	    if (is_inflight(id))
186	      *output_ << fmt::format("L\t{}\t1\t{}\n", id, msg);
187	  }
188	
189	  void flush_all()
190	  {
191	    for (auto id: inflight_)
192	      *output_ << fmt::format("R\t{}\t0\t1\n", id);
193	    inflight_.clear();
194	    output_->flush();
195	  }
196	
197	  /// Load objdump -d output to populate PC→assembly map.
198	  void load_objdump(const std::string& filename)
199	  {
200	    std::ifstream fin(filename);
201	    if (!fin.is_open()) {
202	      spdlog::warn("Failed to open objdump file: {}", filename);
203	      return;
204	    }
205	    std::regex code_regex(R"(^\s*([0-9a-f]+):\t([0-9a-f ]+)\t(.+)$)");
206	    std::string line;
207	    while (std::getline(fin, line)) {
208	      std::smatch match;
209	      if (std::regex_match(line, match, code_regex)) {
210	        auto pc = std::stoull(match[1].str(), nullptr, 16);
211	        auto asm_code = match[3].str();
212	        // Replace tabs with double spaces (same as Python)
213	        for (auto pos = asm_code.find('\t'); pos != std::string::npos;
214	             pos = asm_code.find('\t', pos))
215	        {
216	          asm_code.replace(pos, 1, "  ");
217	          pos += 2;
218	        }
219	        code_map_[pc] = std::move(asm_code);
220	      }
221	    }
222	    spdlog::info("Loaded {} disassembly entries from {}", code_map_.size(),
223	                 filename);
224	  }
225	
226	  bool is_open() const { return output_ != nullptr; }
227	
228	  /// Set when the gate has emitted skip+record end_pc retires. The simulator
229	  /// polls this to break out of its run loop cleanly (see PipelineViewer::
230	  /// wants_exit). Replaces an earlier std::exit(0) that bypassed cleanup.
231	  bool window_complete() const { return window_complete_; }
232	
233	private:
234	  /// On the first start_insn(start_pc) after skip_iters end_pc retires,
235	  /// flip the gate open and realign the on-disk Konata cycle counter to
236	  /// the simulator's total_cycles_ so the recorded window draws at the
237	  /// correct absolute time.
238	  void maybe_open_window(uint64_t pc)
239	  {
240	    if (enabled_ || !gate_)
241	      return;
242	    if (pc != gate_->start_pc)
243	      return;
244	    if (end_retired_ < gate_->skip_iters)
245	      return;
246	    enabled_ = true;
247	    auto delta = total_cycles_ - start_cycle_;
248	    start_cycle_ = total_cycles_;
249	    if (delta > 0)
250	      *output_ << "C\t" << delta << '\n';
251	    spdlog::info(
252	      "Kanata loop gate: window opens at cycle {} (pc {:#x})",
253	      total_cycles_, pc);
254	  }
255	
256	  bool is_inflight(uint64_t id) const { return inflight_.count(id) != 0; }
257	
258	  bool remove_inflight(uint64_t id) { return inflight_.erase(id) > 0; }
259	
260	  void write_header()
261	  {
262	    *output_ << "Kanata\t0004\n";
263	    *output_ << "C=\t0\n";
264	  }
265	
266	  /// Called from retire_insn(). Looks up the PC for `id`, advances the
267	  /// iteration counter when it matches the gate's end_pc, and trips the
268	  /// window_complete_ flag once skip_iters + record_iters retires have
269	  /// been observed. Window opening is handled in start_insn().
270	  void on_retire_pc(uint64_t id, bool /*emitted*/)
271	  {
272	    if (!gate_) {
273	      id_to_pc_.erase(id);
274	      return;
275	    }
276	    auto it = id_to_pc_.find(id);
277	    if (it == id_to_pc_.end())
278	      return;
279	    auto pc = it->second;
280	    id_to_pc_.erase(it);
281	    if (pc != gate_->end_pc)
282	      return;
283	
284	    ++end_retired_;
285	    if (enabled_
286	        && end_retired_ == gate_->skip_iters + gate_->record_iters)
287	    {
288	      auto window_cycles = total_cycles_ - start_cycle_;
289	      spdlog::info(
290	        "Kanata loop window [pc {:#x}..{:#x}]: {} iters, {} insns, {} "
291	        "cycles, IPC={:.3f}",
292	        gate_->start_pc, gate_->end_pc, gate_->record_iters,
293	        recorded_insns_, window_cycles,
294	        window_cycles ? double(recorded_insns_) / double(window_cycles)
295	                      : 0.0);
296	      flush_all();
297	      window_complete_ = true;
298	    }
299	  }
300	
301	  std::ostream* output_ = nullptr;
302	  std::ofstream owned_file_;
303	  std::unordered_map<uint64_t, std::string> code_map_;
304	  std::unordered_set<uint64_t> inflight_;
305	
306	  std::optional<LoopGate> gate_;
307	  std::unordered_map<uint64_t, uint64_t> id_to_pc_;
308	  bool enabled_ = true;
309	  bool window_complete_ = false;
310	  uint64_t end_retired_ = 0;
311	  uint64_t total_cycles_ = 0;
312	  uint64_t start_cycle_ = 0;
313	  uint64_t recorded_insns_ = 0;
314	};
315	
316	} // namespace kanata
