198	  // Caller invariant: the CPU must already be out of reset.
199	  void apply_resume_from_qemu(const std::string& path)
200	  {
201	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
202	      bus{platform.dmi, platform.clk.period()};
203	    hybrid_input_state_ = hybrid::load_state(path);
204	    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
205	    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
206	    // this region to repopulate v0..v31, so the bytes must be in place first.
207	    // Best-effort: mismatched RAM layouts throw, which is louder than silently
208	    // dropping V state.
209	    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
210	      hybrid::stage_v_to_scratch(
211	        *hybrid_input_state_,
212	        platform.main_memory.data,
213	        platform.main_memory.region.base_address);
214	    }
215	    hybrid::ResumeDriver driver(bus);
216	    driver.resume(*hybrid_input_state_);
217	  }
218	
219	  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
220	  // committed PCs and on retire of a `csrw 0x7C0, *` exit-trigger drains
221	  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
222	  //
223	  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
224	  // mode) and the ELF scan is skipped: the binary need not contain a magic
225	  // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
226	  // run -- callers pass exactly one form.
227	  void enable_hybrid_handoff(const std::string& elf_path,
228	                             const std::string& state_out_path,
229	                             std::optional<uint64_t> exit_pc = std::nullopt)
230	  {
231	    hybrid::CsrTrigger trigger;
232	    if (exit_pc) {
233	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
234	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
235	    } else {
236	      auto elf = LIEF::ELF::Parser::parse(elf_path);
237	      if (!elf)
238	        throw std::runtime_error(
239	          "enable_hybrid_handoff: failed to parse " + elf_path);
240	      for (const auto& seg: elf->segments()) {
241	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
242	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
243	        const auto content = seg.content();
244	        const std::span<const uint8_t> bytes{content.data(), content.size()};
245	        trigger.scan_buffer(bytes, seg.virtual_address());
246	      }
247	    }
248	
249	    hybrid_dmi_bus_ = std::make_unique<
250	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
251	                            PLATFORM::dmi_data_width>>(platform.dmi,
252	                                                       platform.clk.period());
253	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_);
254	    if (hybrid_input_state_)
255	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
256	    hybrid_state_path_ = state_out_path;
257	  }
258	
259	  // icount-trigger variant: drain after `target` committed insns retire,
260	  // regardless of PC. Sibling to enable_hybrid_handoff (which is CSR/PC). The
261	  // two modes are mutually exclusive on a single run -- callers pass at most
262	  // one. Multi-hart out of scope per F6: the trigger counts hart-0 retires.
263	  void enable_hybrid_icount_handoff(const std::string& state_out_path,
264	                                    uint64_t icount_target)
265	  {
266	    hybrid::IcountTrigger trigger{icount_target};
267	    spdlog::info("hybrid: icount-trigger mode, target={}", icount_target);
268	
269	    hybrid_dmi_bus_ = std::make_unique<
270	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
271	                            PLATFORM::dmi_data_width>>(platform.dmi,
272	                                                       platform.clk.period());
273	    hybrid_icount_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_);
274	    if (hybrid_input_state_)
275	      hybrid_icount_handoff_->set_passthrough_input(*hybrid_input_state_);
276	    hybrid_state_path_ = state_out_path;
277	  }
278	
279	  void restore_context(const std::string& dir)
280	  {
281	    context_config.dir = dir;
282	    context_config.restore(platform, cpu);
283	  }
284	
285	  void save_context(const std::string& dir)
286	  {
287	    context_config.dir = dir;
288	    context_config.save(platform, cpu);
289	  }
290	
291	  // skip_memory_load: parse the ELF and set the reset vector, but leave
292	  // platform.main_memory untouched. Used in tier-2 hybrid resume where
293	  // QEMU 1's -kernel already populated the shared mmap; re-loading would
294	  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
295	  // to static buffers. The reset vector is still set so the hart has a
296	  // valid fetch target during the post-reset cycles that precede the DMI
297	  // halt+DPC-write resume sequence.
298	  void load_elf(const std::string& path, bool skip_memory_load = false)
299	  {
300	    const auto elf = LIEF::ELF::Parser::parse(path);
301	    if (!elf) {
302	      spdlog::critical("Check if it's a valid ELF file path : {}", path);
303	      exit(1);
304	    }
305	
306	    if (!skip_memory_load)
307	      read_elf_into_memory(
308	        *elf,
309	        static_cast<xlen_t>(platform.main_memory.region.base_address),
310	        platform.main_memory.data);
311	    for (auto& rv: platform.reset_vector)
312	      rv.write(elf->entrypoint());
313	  }
314	
315	  void set_reset_vector(size_t hart, uint64_t addr)
316	  {
317	    if (hart >= platform.reset_vector.size()) {
318	      spdlog::critical("hart {} out of range (max {})", hart,
319	                       platform.reset_vector.size() - 1);
320	      std::exit(EXIT_FAILURE);
321	    }
322	    platform.reset_vector[hart].write(addr);
323	  }
324	
325	  void load_image(const std::string& path, MEM_TYPE type)
326	  {
327	    switch (type) {
328	    case MEM_TYPE::ILM:
329	      if constexpr (requires { cpu.set_ilm({}); }) {
330	        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
331	      } else {
